static inline void end_ui_canvas_draw_circle(int64_t c_handle, int32_t cx, int32_t cy, int32_t radius, uint32_t color) {
    EndCanvas* c = (EndCanvas*)(uintptr_t)c_handle;
    if (!c || !c->pixels || radius <= 0) return;
    int32_t r2 = radius * radius;
    int32_t y0 = (cy - radius) < 0 ? 0 : (cy - radius);
    int32_t y1 = (cy + radius) >= c->height ? c->height - 1 : (cy + radius);
    int32_t x0 = (cx - radius) < 0 ? 0 : (cx - radius);
    int32_t x1 = (cx + radius) >= c->width ? c->width - 1 : (cx + radius);
    for (int32_t y = y0; y <= y1; y++) {
        int32_t dy = y - cy;
        int32_t dy2 = dy * dy;
        for (int32_t x = x0; x <= x1; x++) {
            int32_t dx = x - cx;
            if ((dx * dx + dy2) <= r2) {
                c->pixels[y * c->width + x] = color;
            }
        }
    }
}

